-- AURA catalogue schema, shared by SQLite (#18) and PostgreSQL (#19).
-- Column types use TEXT/INTEGER/portable across both engines.
--
-- Identifiers (`id` and every `*_id` foreign key) hold canonical UUID v4 text:
-- lowercase, 8-4-4-4-12, generated by api/ids.py. No table-level CHECK is added
-- because SQLite cannot attach one to an existing table (it would apply to fresh
-- installs only); the format is enforced at the API boundary and by the seed in
-- api/migrations.py. See docs/DATA-MODEL.md.
--
-- Base tables (users, sessions, folders, objects) plus the multi-platform model
-- (#35: applications, spaces, buckets) and machine-to-machine identities (#38).
-- Additive columns on `users` and `objects` are applied by api/migrations.py, so
-- an existing catalogue keeps its data (see docs/AUTHORIZATION-MATRIX.md).
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  pass_hash TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  csrf TEXT NOT NULL,
  expires_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS folders (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL REFERENCES users(id),
  parent_id TEXT REFERENCES folders(id),
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
-- owner_id is nullable: objects created by a service identity (#38) have no
-- human owner, but always carry a space_id (#35) and an actor_id/actor_kind.
CREATE TABLE IF NOT EXISTS objects (
  id TEXT PRIMARY KEY,
  bucket TEXT NOT NULL,
  object_key TEXT NOT NULL,
  display_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT -1,
  checksum_sha256 TEXT NOT NULL DEFAULT '',
  folder_id TEXT REFERENCES folders(id),
  owner_id TEXT REFERENCES users(id),
  visibility TEXT NOT NULL DEFAULT 'private',
  status TEXT NOT NULL DEFAULT 'pending',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (bucket, object_key)
);
CREATE TABLE IF NOT EXISTS applications (
  id TEXT PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at INTEGER NOT NULL
);
-- `status` is a soft lifecycle flag (active/disabled). A space is never deleted
-- through the API: disabling it stops new identities and new uploads while the
-- existing catalogue rows stay readable (#M04). Added additively on upgrades.
CREATE TABLE IF NOT EXISTS spaces (
  id TEXT PRIMARY KEY,
  application_id TEXT NOT NULL REFERENCES applications(id),
  name TEXT NOT NULL,
  environment TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at INTEGER NOT NULL,
  UNIQUE (application_id, name, environment)
);
CREATE TABLE IF NOT EXISTS buckets (
  id TEXT PRIMARY KEY,
  space_id TEXT NOT NULL REFERENCES spaces(id),
  name TEXT UNIQUE NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS service_identities (
  id TEXT PRIMARY KEY,
  application_id TEXT NOT NULL REFERENCES applications(id),
  space_id TEXT NOT NULL REFERENCES spaces(id),
  name TEXT NOT NULL,
  secret_hash TEXT NOT NULL,
  scopes TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'service',
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  last_used_at INTEGER,
  revoked_at INTEGER,
  rotated_at INTEGER
);
-- Public share links: an unauthenticated, revocable, read-only capability for
-- exactly one object. Only the SHA-256 fingerprint of the link token is stored,
-- so a catalogue dump cannot be replayed as working links. `space_id` is copied
-- from the object at creation so the redemption path can attribute the access to
-- a tenant without a join, and `created_by` keeps attribution even if the creator
-- later loses the role. Rows are never deleted -- revocation is a timestamp, so
-- an audit entry always resolves to a real row. `max_uses` is enforced atomically
-- by Repository.consume_share.
--
-- No foreign key on object_id on purpose: `objects:purge` removes the object row
-- (api/lifecycle.py) and a share must then be a harmless dangling row that
-- answers 404, never a constraint that blocks a purge. Lifecycle deletes the
-- share rows explicitly, before the object row.
CREATE TABLE IF NOT EXISTS object_shares (
  id TEXT PRIMARY KEY,
  object_id TEXT NOT NULL,
  space_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_by_kind TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  content_disposition TEXT NOT NULL DEFAULT 'attachment',
  expires_at INTEGER NOT NULL,
  max_uses INTEGER,
  use_count INTEGER NOT NULL DEFAULT 0,
  revoked_at INTEGER,
  last_used_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS schema_migrations (
  id TEXT PRIMARY KEY,
  applied_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_objects_owner ON objects(owner_id, status);
CREATE INDEX IF NOT EXISTS idx_identities_space ON service_identities(space_id);
CREATE INDEX IF NOT EXISTS idx_shares_object ON object_shares(object_id);
-- idx_objects_space is created by api/migrations.py, after the additive
-- `space_id` column exists on upgraded catalogues.
